                        //    that.tabs?.["tabAdaAkcePSP"]?.gcontent().load();
                        that.tabs.tabAdaAkceRZD.trigger("aktualizuj_rzd", [{}]);
                        that.tabs.tabAdaAkcePSP.trigger("aktualizuj_sdp", [{}]);
