                                            that.setBreadcrumbs([{ caption: that.globals.BAR_Typ_Inst == 10 /* Interface.SrvTypIntalaceEnum.MO */ ? "Položka plánu " + data[0].cislo : "Akce " + data[0].cislo, defaultAction: true }]);
