                            that.statusBarStavAkce.update({ caption: radek.aktivita_s, customClass: (radek.aktivita == 100 /* Interface.AktivitaAkceEnum.Aktivni */) ? "g-state-success g-state-text" : (radek.aktivita == 300 /* Interface.AktivitaAkceEnum.Navrh */) ? "g-state-info g-state-text" : "g-state-error g-state-text" });
