                nastav_menu_stav_realizace(stav_real) {
                    var that = this;
                    if (that.actions) {
                        if (((that.globals.Param_Rezim_Vlastnik == true) && (that.model.Permissions?.JsemVlastnik.value == false)) && (that.model.ixs_fun_az != $.content("main").IxsFunAkt) && (that.model.JsemKompetent == false)) {
                            if (that.actions.actEvidovat) {
                                that.actions.actEvidovat.enabled(false);
                            }
                            if (that.actions.actZaplanovat) {
                                that.actions.actZaplanovat.enabled(false);
                            }
                            if (that.actions.actZkompletovat) {
                                that.actions.actZkompletovat.enabled(false);
                            }
                            if (that.actions.actSchvalit) {
                                that.actions.actSchvalit.enabled(false);
                            }
                            if (that.actions.actVratit) {
                                that.actions.actVratit.enabled(false);
                            }
                            if (that.actions.actPozastavit) {
                                that.actions.actPozastavit.enabled(false);
                            }
                            if (that.actions.actUkoncit) {
                                that.actions.actUkoncit.enabled(false);
                            }
                            if (that.actions.actStornovat) {
                                that.actions.actStornovat.enabled(false);
                            }
                        }
                        else {
                            if (that.actions.actEvidovat) {
                                that.actions.actEvidovat.enabled(stav_real == 310 /* Interface.StavRealizaceAkceEnum.Navrh */ ? true : false);
                            }
                            if (that.actions.actZaplanovat) {
                                that.actions.actZaplanovat.enabled(stav_real == 320 /* Interface.StavRealizaceAkceEnum.Evidovano */ ? true : false);
                            }
                            if (that.actions.actZkompletovat) {
                                that.actions.actZkompletovat.enabled(stav_real == 330 /* Interface.StavRealizaceAkceEnum.Zaplanovano */ ? true : false);
                            }
                            if (that.actions.actSchvalit) {
                                that.actions.actSchvalit.enabled(stav_real == 340 /* Interface.StavRealizaceAkceEnum.Zkompletovano */ ? true : false);
                            }
                            if (that.actions.actVratit) {
                                that.actions.actVratit.enabled(((stav_real > 320 /* Interface.StavRealizaceAkceEnum.Evidovano */) || (stav_real <= 140 /* Interface.StavRealizaceAkceEnum.Zpozdeno */)) ? true : false);
                            }
                            if (that.actions.actPozastavit) {
                                that.actions.actPozastavit.enabled(((stav_real >= 110 /* Interface.StavRealizaceAkceEnum.Schvaleno */) && (stav_real <= 140 /* Interface.StavRealizaceAkceEnum.Zpozdeno */)) ? true : false);
                            }
                            if (that.actions.actUkoncit) {
                                that.actions.actUkoncit.enabled((((stav_real >= 110 /* Interface.StavRealizaceAkceEnum.Schvaleno */) && (stav_real <= 140 /* Interface.StavRealizaceAkceEnum.Zpozdeno */)) || (stav_real == 510 /* Interface.StavRealizaceAkceEnum.Pozastaveno */)) ? true : false);
                            }
                            if (that.actions.actStornovat) {
                                that.actions.actStornovat.enabled((stav_real != 910 /* Interface.StavRealizaceAkceEnum.Stornovano */) ? true : false);
                            }
                        }
                    }
                }
